package com.myeshopping.returnrefundservice.controller;
import com.myeshopping.returnrefundservice.dto.*; import com.myeshopping.returnrefundservice.entity.ReturnRequestEntity; import com.myeshopping.returnrefundservice.service.ReturnRefundService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.UUID;
@RestController @RequestMapping("/api/v1/returns") @RequiredArgsConstructor public class ReturnRefundController { private final ReturnRefundService service; private final com.myeshopping.returnrefundservice.service.OrderCancellationService cancellationService; @PostMapping("/orders/{orderId}/cancel") public ResponseEntity<ApiResponse<java.util.Map<String,Object>>> cancel(@PathVariable Long orderId,@RequestBody(required=false) java.util.Map<String,String> body){String reason=body==null?null:body.get("reason");return ok("Order cancelled and refunded",cancellationService.cancelOrReturn(orderId,reason));} @PostMapping public ResponseEntity<ApiResponse<ReturnRequestEntity>> create(@Valid @RequestBody ReturnRequest request){return ok("Return requested successfully",service.create(request));} @GetMapping("/{id}") public ResponseEntity<ApiResponse<ReturnRequestEntity>> get(@PathVariable Long id){return ok("Return request fetched successfully",service.get(id));} @PostMapping("/{id}/transition") public ResponseEntity<ApiResponse<ReturnRequestEntity>> transition(@PathVariable Long id,@Valid @RequestBody TransitionRequest request){return ok("Return transitioned successfully",service.transition(id,request.getStatus()));} @PostMapping("/{id}/refund") public ResponseEntity<ApiResponse<ReturnRequestEntity>> refund(@PathVariable Long id,@Valid @RequestBody TransitionRequest request){return ok("Refund transitioned successfully",service.refund(id,request.getStatus()));} private <T> ResponseEntity<ApiResponse<T>> ok(String message,T data){return ResponseEntity.ok(ApiResponse.<T>builder().success(true).message(message).data(data).timestamp(Instant.now()).correlationId(UUID.randomUUID()).build());} }
